    --xt-text: #000000;                     /* 纯黑正文 */
    --xt-text-sub: #8e8e93;                 /* iOS标准灰色时间戳 */
    --xt-accent: #e0a900;                   /* 苹果备忘录经典金黄色 */
    --xt-radius: 24px;                      
    --xt-font: -apple-system, 'SF Pro Display', BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.05); 
    padding: 24px 22px 65px 22px !important; /* 预留底部栏空间 */
    position: relative;
    overflow: hidden;
}

/* 2. 隐藏自带头像（加上最高优先级，防止旧头像先闪出来） */
.xt-header {
    display: none !important;
}

/* 3. 顶部导航栏：左侧“备忘录”，右侧精确复刻【分享箭头圈】与【更多圈】 */
.xt-section {
    margin: 0 0 16px 0 !important;
    position: relative;
}
.xt-section-title {
    color: var(--xt-accent) !important;
    font-size: 17px !important;
    font-weight: 400 !important;
    display: inline-flex;
    align-items: center;
    letter-spacing: -0.4px !important;
    margin-bottom: 0px !important;
}
/* 左侧返回小箭头（苹果官方粗细比例） */
.xt-section-title::before {
    content: "";
    display: inline-block;
    width: 10px;
    height: 10px;
    border-left: 2.5px solid var(--xt-accent);
    border-bottom: 2.5px solid var(--xt-accent);
    transform: rotate(45deg);
    margin-right: 5px;
    margin-top: -1px;
}
/* 右侧：用带有完美线宽的 SVG 矢量图直接绘制苹果官方的“分享”和“更多”按钮 */
.xt-section-title::after {
    content: "";
    position: absolute;
    right: 2px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    gap: 18px; /* 两个图标的精确间距 */
    width: 64px;
    height: 24px;
    /* 注入纯正的 Apple Share Icon & More Icon 矢量数据 */
    background-image: 
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r=\"10\"/><path d=\"M12 16V8M12 8l-3 3M12 8l3 3\"/></svg>'), 
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="2"><circle cx="12" cy="12" r=\"10\"/><circle cx=\"8\" cy=\"12\" r=\"1\" fill=\"%23e0a900\"/><circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"%23e0a900\"/><circle cx=\"16\" cy=\"12\" r=\"1\" fill=\"%23e0a900\"/></svg>');
    background-repeat: no-repeat;
    background-size: 23px 23px, 23px 23px;
    background-position: left center, right center;
}

/* 4. 时间戳区域：严格居中，字号缩小，字重降低 */
.xt-section-body {
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    text-align: center !important;
    color: var(--xt-text-sub) !important;
    font-size: 12px !important;
    font-weight: 400;
    margin-top: 6px !important;
    letter-spacing: -0.1px;
}
/* 智能拼装符合中国用户手机习惯的日期格式 */
.xt-section-body::before {
    content: "2026年6月10日 "; 
    display: inline-block;
}

/* 5. 标题：极粗，紧凑排版 */
.xt-text {
    background: transparent !important;
    padding: 16px 0 6px 0 !important;
    color: var(--xt-text) !important;
    font-size: 25px !important;
    font-weight: 800 !important;
    border-radius: 0 !important;
    text-align: left !important;
    letter-spacing: -0.6px;
}

/* 6. 独白文本：严格左对齐，去除括号，优化间距和行高 */
.xt-quote {
    background: transparent !important;
    padding: 2px 0 !important;
    color: #1c1c1e !important;
    font-size: 16px !important;
    line-height: 1.6 !important;
    text-align: left !important;
}
.xt-quote::before, .xt-quote::after {
    display: none !important;              /* 彻底抹除原主题的大括号 */
}

/* 7. 底部工具栏：使用极细的高清线描 SVG 图标，1:1 复刻 iOS 备忘录底部的四个功能按键 */
.xt-root::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 52px;
    background: #ffffff;
    border-top: 0.5px solid #d1d1d6;       /* 苹果标准的极细分割线 */
    padding: 0 24px;
    /* 依次注入：核对清单、相机、手写、新备忘录的官方同款样式 */
    background-image: 
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><path d="m9 11 2 2 4-4"/></svg>'),
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d=\"M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z\"/><circle cx=\"12\" cy=\"13\" r=\"4\"/></svg>'),
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill=\"none\" stroke="%23e0a900" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d=\"m12 14 4-4M4 20h16\"/><path d=\"M15 4h5v5M15 9l5-5\"/></svg>'),
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d=\"M12 20h9M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z\"/></svg>');
    background-repeat: no-repeat;
    background-size: 22px 22px, 24px 24px, 22px 22px, 21px 21px;
    background-position: 6% center, 36% center, 65% center, 94% center;
}

/* 8. 隐藏不需要的系统脚标组件 */
.xt-footer {
    display: none !important;
}

data.xinshengLayout:
